103	export function isCommandNoise(text: string): boolean {
104	  const t = text.trimStart();
105	  return (
106	    t.startsWith("<command-name>") ||
107	    t.startsWith("<command-message>") ||
108	    t.startsWith("<local-command-") ||
109	    t.startsWith("<bash-input>") ||
110	    t.startsWith("<bash-stdout>") ||
111	    t.startsWith("Caveat:")
112	  );
113	}
114	
115	// 一个 turn 由「真·用户提问」开启。判定的难点全在于：CLI 会往对话流里塞一堆
116	// 长得和用户提问一模一样的 user 文本消息（skill 触发时的 "Base directory for
117	// this skill: …"、后台 agent 完成的 <task-notification>、Stop hook 的反馈、
118	// "Continue from where you left off."）。把它们误判成 turn-start 的后果不是多
119	// 一个节点那么轻——它会把**后续 assistant 的最终回复整段劫走**挂到假 turn 上，
120	// 真 turn 只剩工具调用、response 为空，UI 里就是一条永远「正在生成…」的僵尸。
121	// 本机 337 个 turn 实测：修前 45 条空 response 带工具，其中 44 条是这么来的。
122	//
123	// 判据用结构字段、不用文本前缀白名单（前缀会随 CLI 版本漂）：
124	//   isMeta === true          —— 83 条注入全中，257 条真用户零误杀
125	//   promptSource === "system" —— task-notification 专属；真用户是 typed/sdk/queued
126	//   interruptedMessageId      —— Esc 打断的占位消息（全库 522 条），这两个字段都没有
127	//   isCompactSummary / isVisibleInTranscriptOnly —— /compact 注入的历史摘要
128	// isCommandNoise 的文本闸留作老版本 jsonl 的兜底（那时还没有这些字段）。
129	export function isTurnStart(e: CliRawEntry): boolean {
130	  if (e.type !== "user") return false;
131	  if (isToolResultEntry(e)) return false;
132	  if (e.isMeta === true) return false;
133	  if (e.promptSource === "system") return false;
134	  if (e.interruptedMessageId !== undefined) return false;
135	  if (e.isCompactSummary === true) return false;
136	  if (e.isVisibleInTranscriptOnly === true) return false;
137	  const text = userText(e);
138	  if (!text || !text.trim()) return false;
139	  if (isCommandNoise(text)) return false;
140	  return true;
141	}
142	
143	// 宽松判据：任何带文本的非 tool_result user 消息都能当 turn-start（含被严格
144	// 判据挡掉的 meta / system / 命令噪声）。只用于严格判据找不到主时的兜底。
145	// 绝不能放行 compact summary（那不是对话起点，否则会导致 turn-start 错配）。
146	export function looseTurnStart(e: CliRawEntry): boolean {
147	  if (e.type !== "user") return false;
148	  if (isToolResultEntry(e)) return false;
149	  if (e.isCompactSummary === true) return false;
150	  if (e.isVisibleInTranscriptOnly === true) return false;
151	  return Boolean(userText(e)?.trim());
152	}
153	
154	// ── turn 归属 ───────────────────────────────────────────────────────────────
155	
156	// byUuid 必须收**全部**带 uuid 的 entry（含 type:"system" 的 compact/边界标记）——
157	// CLI 在每个 turn 之间插 system 节点承载父链，过滤掉会把链打断、让每个 turn
158	// 变成孤根。ownerTurn 上溯时需穿过这些非对话节点继续走。
159	export function indexByUuid(
160	  entries: Iterable<CliRawEntry>,
161	): Map<string, CliRawEntry> {
162	  const byUuid = new Map<string, CliRawEntry>();
163	  for (const e of entries) if (typeof e.uuid === "string") byUuid.set(e.uuid, e);
164	  return byUuid;
165	}
166	
167	// 每条 entry 归属哪个 turn-start（沿 parentUuid 上溯到最近的 turn-start）。
168	// 同一套上溯按不同判据跑两遍 —— 见 makeTurnOwnership 的取舍。
169	export function makeOwnerResolver(
170	  byUuid: Map<string, CliRawEntry>,
171	  isStart: (e: CliRawEntry) => boolean,
172	) {
173	  const turnOf = new Map<string, string | null>();
174	  return function ownerTurn(uuid: string): string | null {
175	    const cached = turnOf.get(uuid);
176	    if (cached !== undefined) return cached;
177	    const e = byUuid.get(uuid);
178	    if (!e) {
179	      turnOf.set(uuid, null);
180	      return null;
181	    }
182	    // 占位防环（坏 jsonl 自指）。
183	    turnOf.set(uuid, null);
184	    let owner: string | null;
185	    if (isStart(e)) owner = e.uuid as string;
186	    else owner = e.parentUuid ? ownerTurn(e.parentUuid) : null;
187	    turnOf.set(uuid, owner);
188	    return owner;
189	  };
190	}
191	
192	export type TurnOwnership = {
193	  // 严格优先、宽松兜底的归属解析。
194	  resolveOwner: (uuid: string) => string | null;
195	  // 被宽松判据认领出来的兜底起点（import 侧要把它们一并组装成节点）。
196	  fallbackStartIds: Set<string>;
197	};
198	
199	// 兜底承载：`claude --continue` / fork 出来的 jsonl，开头可能压根没有真用户
200	// 提问（链头是 "Continue from where you left off." 这类 meta，甚至直接是

