for (const start of starts) {
  const id = start.uuid as string;
  const members = (membersByTurn.get(id) ?? []).sort(
    (a, b) => ms(a.timestamp) - ms(b.timestamp),
  );

  const textParts: string[] = [];
  const toolCalls: ToolCall[] = [];
  let sumInput = 0;
  let sumOutput = 0;
  let sumCacheRead = 0;
  let sumCacheCreation = 0;
  let lastUsage: Usage | undefined;
  // finalStart 状态机，与 run-bus 的流式版同构：tool_use/thinking 块是结构性
  // 中断，其后的首个 text part 即当前「最终答复」候选段的起点（part 索引）。
  let finalPartIdx = 0;
  let pendingBreak = false;
  const pushText = (t: string) => {
    if (pendingBreak) {
      finalPartIdx = textParts.length;
      pendingBreak = false;
    }
    textParts.push(t);
  };
  for (const m of members) {
    const startedAt = ms(m.timestamp);
    const c = m.message?.content;
    if (m.message?.usage) {
      const u = m.message.usage;
      lastUsage = u;
      sumInput += u.input_tokens ?? 0;
      sumOutput += u.output_tokens ?? 0;
      sumCacheRead += u.cache_read_input_tokens ?? 0;
      sumCacheCreation += u.cache_creation_input_tokens ?? 0;
    }
    if (typeof c === "string") {
      if (c.trim()) pushText(c);
      continue;
    }
    if (!Array.isArray(c)) continue;
    for (const b of c) {
      if (b.type === "text" && b.text?.trim()) {
        pushText(b.text);
      } else if (b.type === "tool_use" && b.id) {
        if (textParts.length) pendingBreak = true;
        const res = resultById.get(b.id);
        toolCalls.push({
          id: b.id,
          name: b.name ?? "tool",
          input: b.input ?? null,
          output: res?.output ?? null,
          stderr: res?.stderr ?? null,
          status: res ? (res.isError ? "error" : "done") : "done",
          durationMs: null,
          startedAt,
          endedAt: startedAt,
        });
      } else if (b.type === "thinking") {
        // thinking 内容 v1 丢弃，但它仍是段落中断信号（interleaved thinking
        // 下最终答复前必有一段思考）。
        if (textParts.length) pendingBreak = true;
      }
    }
  }

  const startMs = ms(start.timestamp);
  const endMs = members.length > 0 ? ms(members[members.length - 1].timestamp) : startMs;
  const durationMs = endMs > startMs ? endMs - startMs : 0;

  const parentTurn = start.parentUuid ? resolveOwner(start.parentUuid) : null;
