98	// Metadata for a tool call that spawned a background task. Sourced from
99	// claude's `system` task_started / task_progress / task_updated /
100	// task_notification lines (see @sm/agent EventType.Task), which carry live
101	// progress the tool_use block alone doesn't have. Every field optional: the
102	// CLI feeds them in across phases (taskType + prompt at start, usage during,
103	// summary at the end), and old rows / other backends have none of it.
104	//
105	// ⚠️ This is NOT "sub-agent metadata", though it was named that until we
106	// learned better. A slow *foreground* Bash gets the exact same treatment
107	// (task_type: local_bash) — as does Workflow. Treating "has task meta" as
108	// "is a sub-agent" is what made command output vanish: the row got claimed
109	// into a sub-agent group whose report field preferred `summary`, and for a
110	// local_bash the summary is just the description echoed back.
111	export type TaskMeta = {
112	  taskId?: string;
113	  // Only present on task_started — later phases patch onto the same row, so
114	  // the merged meta keeps it. Absent = pre-0.3.3 SDK or a non-claude backend;
115	  // callers fall back to the taskId prefix (a/b/w) then to the tool name.
116	  taskType?: TaskKind;
117	  phase?: string;          // "started" | "progress" | "updated" | "completed"
118	  subagentType?: string;   // "general-purpose" | "Explore" | custom agent name
119	  description?: string;    // short label; live-updated to the current step
120	  prompt?: string;         // the full task handed over (the script, for workflows)
121	  status?: string;         // "completed" | "failed" | ... (from task_updated)
122	  lastToolName?: string;   // tool the sub-agent is running right now
123	  totalTokens?: number;
124	  toolUses?: number;
125	  durationMs?: number;
126	  // The task's final report. Trustworthy for local_agent only — for
127	  // local_bash it's the description echoed back, and for local_workflow it's
128	  // 'Dynamic workflow "..." completed'. Never show it in place of output.
129	  summary?: string;
130	  outputFile?: string;
131	  workflowName?: string;   // meta.name from the workflow script
132	  workflowProgress?: WorkflowProgressEntry[];
133	};
