135	export type ToolCall = {
136	  // The CLI's id (e.g. "toolu_017sqa1c..."). Stable across the start +
137	  // result events so the UI can merge them.
138	  id: string;
139	  name: string;          // "Bash" | "Read" | "Edit" | "WebFetch" | ...
140	  input: unknown;        // shape varies per tool; pretty-printed as JSON in UI
141	  // null until the matching tool_result arrives. Often a multi-line
142	  // string (Bash stdout); UI clamps display.
143	  output: string | null;
144	  // Captured separately from `content` for Bash since claude includes
145	  // both in tool_use_result. UI shows stderr only when non-empty.
146	  stderr: string | null;
147	  status: ToolCallStatus;
148	  // Wall-clock ms from start emit to done emit. null while running.
149	  durationMs: number | null;
150	  // Server-side timestamps for ordering + duration computation.
151	  startedAt: number;
152	  endedAt: number | null;
153	  // Stage 22: non-null when this call was made *by a sub-agent* rather than
154	  // the main agent — it carries the tool_use id of the Task/Agent call that
155	  // spawned it. Absent/null = main agent (all pre-Stage-22 rows). The UI
156	  // groups children under their parent instead of one flat chain.
157	  parentToolUseId?: string | null;
158	  // Present when this call spawned a background task — a sub-agent, a
159	  // long-running Bash, or a Workflow. `agent.taskType` says which; the field
160	  // name is a historical misnomer kept to avoid a data migration (it is
161	  // serialized into nodes.tool_calls_json).
162	  agent?: TaskMeta;
