25	import { TurnCard } from "./TurnCard";
26	
27	// #7: the unified reading/chat surface for EVERY mode (chat /
28	// project). One thread anchored at the active node: ancestors above, the
29	// first-child chain below, non-thread children folded into "↳ N 个分支"
30	// rows. Cards are fully interactive (TurnCard: edit question, ⌘K selection
31	// branching via BranchPopover, regenerate, copy, interaction forms), and the
32	// sticky bottom composer continues the displayed lineage — this replaced the
33	// old NodeFullView fullscreen reader (issues #2/#4/#7).
34	
35	function truncate(text: string, max: number) {
36	  return text.length > max ? `${text.slice(0, max)}...` : text;
37	}
38	
39	function firstRoot(nodes: Record<string, ChatNode>, rootNodeId?: string | null) {
40	  if (rootNodeId && nodes[rootNodeId]) return nodes[rootNodeId];
41	  return Object.values(nodes)
42	    .filter((n) => !n.parentId)
43	    .sort(nodeSort)[0] ?? null;
44	}
45	
46	// How close to the bottom (px) still counts as "following" — scrolling
47	// further up than this pauses the stream auto-follow until the user returns.
48	const FOLLOW_SLACK_PX = 120;
